      tags$ul(
        class = "list-unstyled",
        style = "line-height: 1.8;",

        tags$li(
          style = "margin-bottom: 0.8em;",
          "Dunlop, J., von Takach, B., Dempster, T., Jolly, C. J., Letnic, M.,",
