          "& Phillips, B. L. (2025). Quantifying the potential impact of the cane",
          "toad (", tags$em("Rhinella marina"), ") on biodiversity in Australia's",
          "Pilbara region.", tags$em("Scientific Reports"), ", ", tags$em("15"), "(1), 37566.",
          tags$a(href = "https://doi.org/10.1038/s41598-025-24017-4",
                 target = "_blank", "https://doi.org/10.1038/s41598-025-24017-4")
        ),

        tags$li(
          style = "margin-bottom: 0.8em;",
          "Southwell, D., Tingley, R., Bode, M., Nicholson, E., & Phillips, B. (2017).",
          "Cost and feasibility of a barrier to halt the spread of invasive cane toads",
          "in arid Australia: Incorporating expert knowledge into model-based",
          "decision-making.", tags$em("Journal of Applied Ecology"), ", ",
          tags$em("54"), "(1), 216–224.",
          tags$a(href = "https://doi.org/10.1111/1365-2664.12744",
                 target = "_blank", "https://doi.org/10.1111/1365-2664.12744")
        ),

        tags$li(
          style = "margin-bottom: 0.8em;",
          "Tingley, R., Phillips, B. L., Letnic, M., Brown, G. P., Shine, R.,",
          "& Baird, S. J. E. (2013). Identifying optimal barriers to halt the",
          "invasion of cane toads ", tags$em("Rhinella marina"), " in arid Australia.",
          tags$em("Journal of Applied Ecology"), ", ", tags$em("50"), ", 129–137.",
          tags$a(href = "https://doi.org/10.1111/1365-2664.12021",
                 target = "_blank", "https://doi.org/10.1111/1365-2664.12021")
        )
      ),

      hr(),

      p(
        class = "text-muted small",
        "Forecast last updated: ", strong(updated), ". ",
        tags$a(href = "https://toadfree.zone", target = "_blank",
               "toadfree.zone")
      )
    )
  )
)

# ---- Server ----
server <- function(input, output, session) {

  output$map <- renderLeaflet({
    leaflet() |>
      addProviderTiles(
        "Esri.WorldTopoMap",
        options = providerTileOptions(opacity = 0.75)
      ) |>

      addPolygons(
        data        = tcz_boundary,
        color       = "#cc0000",
        weight      = 2,
        fillOpacity = 0.05,
        label       = "Toad Containment Zone",
        group       = "TCZ Boundary"
      ) |>
      addPolygons(
        data        = pastoral_boundaries,
        color       = "#1a6faf",
        weight      = 1,
        fillOpacity = 0.05,
        group       = "Pastoral Boundaries"
      ) |>
      addLegend(
        position = "bottomright",
        pal      = pal,
        values   = c(0, 1),
        title    = "Probability of<br>toad arrival",
        opacity  = 0.9
      ) |>
      addLayersControl(
        overlayGroups = c("TCZ Boundary", "Pastoral Boundaries"),
        options = layersControlOptions(collapsed = FALSE)
      ) |>
      fitBounds(
        lng1 = initial_bounds$lng1,
        lat1 = initial_bounds$lat1,
        lng2 = initial_bounds$lng2,
        lat2 = initial_bounds$lat2
      )
  })

  # Redraw only the point layer when the year slider changes
  observe({
    yr <- input$year
    d  <- prob_data |> filter(year == yr, prob > 0)

    leafletProxy("map") |>
      # Redraw grey background with year-specific popup
      clearGroup("background") |>
      addCircleMarkers(
        data        = all_points,
        lng         = ~lon,
        lat         = ~lat,
        radius      = 3,
        fillColor   = "#aaaaaa",
        fillOpacity = 0.4,
        stroke      = FALSE,
        group       = "background",
        popup       = paste0(
          "<b>Waterpoint</b><br>",
          "Probability colonised by <b>", yr, "</b>: <b>0%</b>"
        )
      ) |>
      clearGroup("points") |>
      addCircleMarkers(
        data        = d,
        lng         = ~lon,
        lat         = ~lat,
        radius      = 4,
        fillColor   = ~pal(prob),
        fillOpacity = 0.85,
        stroke      = FALSE,
        group       = "points",
        popup       = ~paste0(
          "<b>Waterpoint</b><br>",
          "Probability colonised by <b>", yr, "</b>: ",
          "<b>", round(prob * 100), "%</b><br>",
          "Median expected arrival year: <b>", mean_arrival, "</b>"
        )
      )
  })
}

shinyApp(ui, server)
